"""Plain text absence notices for parents."""

from typing import List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed


def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} given "
                f"with student {student.student_id}"
            )


def _compose(student: Student, dates: list) -> str:
    count = len(dates)
    word = "day" if count == 1 else "days"
    lines = (f"- {item.isoformat()}" for item in dates)
    listed = "\n".join(lines)
    return (
        f"{student.first_name} {student.last_name} "
        f"missed {count} {word}:\n{listed}"
    )


# ---
def build_notice(student: Student, marks: list) -> str:
    """Short notice naming the student and absent dates."""
    _check_owner(student, marks)
    dates = sorted(set(days_missed(marks)))
    if not dates:
        raise ValueError("no absences to report")
    return _compose(student, dates)
